INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind sinnvolle Namen nur für Variablen wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Funktionen und Klassen profitieren"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit kleinen Funktionen?', 3, '[{"text": "Lesbarkeit erhöhen", "correct": true, "because": "Kompakte Logik klarer"}, {"text": "Code schneller machen", "correct": false, "because": "Kein Performance-Fokus"}, {"text": "Mehr Features", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten sinnvolle Namen und kleine Funktionen?', 5, '[{"text": "Verständlichkeit", "correct": true, "because": "Namen erklären Zweck"}, {"text": "Wartbarkeit", "correct": true, "because": "Kleine Einheiten einfacher"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sparse Comments erklären nur Komplexes. b) Sie ersetzen gute Namen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Namen bleiben zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Meaningful Names?', 4, '[{"text": "Klarheit", "correct": false, "because": "Kern des Prinzips"}, {"text": "Beschreibung", "correct": false, "because": "Namen sollen erklären"}, {"text": "Farbschema", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kleine Funktionen mehr Code erzeugen?', 2, '[{"text": "Ja", "correct": true, "because": "Logik wird aufgeteilt"}, {"text": "Nein", "correct": false, "because": "Trennung erhöht oft Zeilen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem Prinzip sinnvoller Namen?', 3, '[{"text": "calculateTotalPrice", "correct": true, "because": "Beschreibt Zweck"}, {"text": "x1", "correct": false, "because": "Unklar"}, {"text": "tmp", "correct": false, "because": "Nicht aussagekräftig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern kleine Funktionen?', 5, '[{"text": "Testbarkeit", "correct": true, "because": "Kleine Einheiten prüfbar"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Kompakte Logik nutzbar"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Sparse Comments reduzieren Overhead. b) Sie machen Namen überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Namen bleiben wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Sparse Comments?', 4, '[{"text": "Klarheit im Code", "correct": false, "because": "Reduziert Kommentarbedarf"}, {"text": "Sinnvolle Namen", "correct": false, "because": "Ergänzen Kommentare"}, {"text": "Viele Erklärungen", "correct": true, "because": "Sollten sparsam sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind kleine Funktionen ohne Planung möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Kann spontan erfolgen"}, {"text": "Nein", "correct": false, "because": "Planung hilfreich, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme lösen sinnvolle Namen?', 4, '[{"text": "Missverständnisse", "correct": true, "because": "Klarheit im Zweck"}, {"text": "Schwere Lesbarkeit", "correct": true, "because": "Selbsterklärend"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sparse Comments nur für Experten sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Meaningful Names?', 3, '[{"text": "Aussagekraft", "correct": true, "because": "Namen erklären Zweck"}, {"text": "Kürze", "correct": false, "because": "Klarheit über Kürze"}, {"text": "Viele Buchstaben", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kleine Funktionen fördern Übersicht. b) Sie garantieren weniger Bugs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bugs nicht garantiert reduziert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben kleine Funktionen?', 5, '[{"text": "Mehr Funktionen", "correct": true, "because": "Logik aufgeteilt"}, {"text": "Höherer Aufrufaufwand", "correct": true, "because": "Kann Overhead erhöhen"}, {"text": "Schwerere Tests", "correct": false, "because": "Einfacher prüfbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Sparse Comments unwichtig?', 3, '[{"text": "Klarer Code", "correct": false, "because": "Reduziert Kommentarbedarf"}, {"text": "Gegebenenfalls Warum", "correct": false, "because": "Wichtige Kommentare"}, {"text": "Jede Zeile erklären", "correct": true, "because": "Sollte vermieden werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Meaningful Names die Zeilenanzahl?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Namen, kein Code"}, {"text": "Ja", "correct": false, "because": "Länge der Namen irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kleine Funktionen Refactoring erleichtern?', 2, '[{"text": "Ja", "correct": true, "because": "Kompakte Einheiten änderbar"}, {"text": "Nein", "correct": false, "because": "Übersicht hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt Meaningful Names?', 4, '[{"text": "DRY", "correct": true, "because": "Wiederverwendung mit Klarheit"}, {"text": "LSP", "correct": false, "because": "Vererbungsspezifisch"}, {"text": "ISP", "correct": false, "because": "Interfacespezifisch"}]');
